/**
 * The 44 named guard mutants (GH-240 test plan §4, TC-CAP-058).
 *
 * Each entry mutates one declared source by an exact replacement and names the
 * narrow suite that must fail, plus a token the failure output must contain.
 */
export type CapsuleMutant = {
  readonly id: string;
  readonly guard: string;
  readonly file: string;
  readonly distFile?: string;
  readonly find: string;
  readonly replace: string;
  readonly distFind?: string;
  readonly distReplace?: string;
  readonly suite: string;
  readonly signal: string;
  /** Replace every occurrence in the target file (default: first only). */
  readonly all?: boolean;
};

